import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(T):
        try:
            M = int(next(iterator))
            N = int(next(iterator))
            s = next(iterator)
        except StopIteration:
            break

        n = len(s)

        def count_exact(target_char, target_count):
            prefix_counts = [0] * (n + 1)
            current = 0
            for i in range(n):
                if s[i] == target_char:
                    current += 1
                prefix_counts[i+1] = current

            total = 0
            if target_count == 0:
                prev = 0
                for i in range(1, n + 1):
                    if prefix_counts[i] == 0:
                        total += i
                    else:
                        prev = i
                return total

            left = 0
            right = 0
            while right <= n:
                if right < n:
                    if prefix_counts[right+1] - prefix_counts[left] == target_count:
                        right += 1
                        total += 1
                    elif prefix_counts[right+1] - prefix_counts[left] > target_count:
                        left += 1
                    else:
                        right += 1
                else:
                    break

            return total

        count_r = count_exact('R', M)
        count_k = count_exact('K', N)

        results.append(f"{count_r} {count_k}")

    print('\n'.join(results))

if __name__ == "__main__":
    solve()
